CREATE TABLE "account_emailaddress" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "verified" bool NOT NULL, "primary" bool NOT NULL, "user_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "email" varchar(254) NOT NULL);
CREATE TABLE "account_emailconfirmation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created" datetime NOT NULL, "sent" datetime NULL, "key" varchar(64) NOT NULL UNIQUE, "email_address_id" integer NOT NULL REFERENCES "account_emailaddress" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "ai_aigenerationjob" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "job_type" varchar(40) NOT NULL, "status" varchar(20) NOT NULL, "course_id" integer unsigned NOT NULL CHECK ("course_id" >= 0), "topic_id" integer unsigned NOT NULL CHECK ("topic_id" >= 0), "difficulty" varchar(20) NOT NULL, "count" smallint unsigned NOT NULL CHECK ("count" >= 0), "error_message" text NOT NULL, "result" text NOT NULL CHECK ((JSON_VALID("result") OR "result" IS NULL)), "created" datetime NOT NULL, "updated" datetime NOT NULL, "created_by_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "source_material" text NOT NULL, "learning_document_id" bigint NULL REFERENCES "ai_learningdocument" ("id") DEFERRABLE INITIALLY DEFERRED);

