CREATE TABLE "ai_learningchunk" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "page_start" integer unsigned NOT NULL CHECK ("page_start" >= 0), "page_end" integer unsigned NOT NULL CHECK ("page_end" >= 0), "text" text NOT NULL, "document_id" bigint NOT NULL REFERENCES "ai_learningdocument" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "ai_learningdocument" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "course_id" integer unsigned NOT NULL CHECK ("course_id" >= 0), "original_name" varchar(255) NOT NULL, "file" varchar(100) NOT NULL, "status" varchar(20) NOT NULL, "page_count" integer unsigned NOT NULL CHECK ("page_count" >= 0), "chunk_count" integer unsigned NOT NULL CHECK ("chunk_count" >= 0), "error_message" text NOT NULL, "created" datetime NOT NULL, "updated" datetime NOT NULL, "created_by_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "analytics_errortype" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "slug" varchar(50) NOT NULL UNIQUE, "label" varchar(100) NOT NULL, "category" varchar(50) NOT NULL);
CREATE TABLE "analytics_mistakerecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "occurred_at" datetime NOT NULL, "answer_id" bigint NOT NULL UNIQUE REFERENCES "reviews_answer" ("id") DEFERRABLE INITIALLY DEFERRED, "question_id" bigint NOT NULL REFERENCES "questions_question" ("id") DEFERRABLE INITIALLY DEFERRED, "student_id" bigint NOT NULL REFERENCES "users_user" ("id") DEFERRABLE INITIALLY DEFERRED, "topic_id" bigint NOT NULL REFERENCES "questions_topic" ("id") DEFERRABLE INITIALLY DEFERRED, "error_type_id" bigint NULL REFERENCES "analytics_errortype" ("id") DEFERRABLE INITIALLY DEFERRED, "ai_feedback" text NOT NULL, "student_image" varchar(100) NULL, "student_note" text NOT NULL, "faculty_note" text NOT NULL, "faculty_noted_at" datetime NULL);
