INSERT INTO "ai_aigenerationjob" VALUES(1,'question_generate','succeeded',13,66,'easy',5,'','{"variations": [{"stem": "What is the degree of the polynomial 4x^3 - 2x + 7?", "concept_tag": "polynomial degree", "correct_label": "A", "choices": [{"label": "A", "text": "3", "is_correct": true}, {"label": "B", "text": "4", "is_correct": false}, {"label": "C", "text": "1", "is_correct": false}, {"label": "D", "text": "2", "is_correct": false}], "explanation_steps": ["Step 1: Look for the term with the highest exponent of x that has a non\u2011zero coefficient.", "Step 2: In 4x^3 - 2x + 7 the highest exponent is 3, so the degree is 3."], "solution_summary": "Final answer: B because the highest power of x in the polynomial is x^3, giving degree 3."}, {"stem": "Solve for x: 2x + 5 = 13.", "concept_tag": "linear equation", "correct_label": "D", "choices": [{"label": "A", "text": "x = 5", "is_correct": false}, {"label": "B", "text": "x = 3", "is_correct": false}, {"label": "C", "text": "x = 6", "is_correct": false}, {"label": "D", "text": "x = 4", "is_correct": true}], "explanation_steps": ["Step 1: Subtract 5 from both sides to get 2x = 8.", "Step 2: Divide both sides by 2 to obtain x = 4."], "solution_summary": "Final answer: C because subtracting 5 gives 2x = 8 and dividing by 2 yields x = 4."}, {"stem": "What is the degree of the polynomial 3x^2 - 5x + 7?", "concept_tag": "Polynomial degree", "correct_label": "D", "choices": [{"label": "A", "text": "3", "is_correct": false}, {"label": "B", "text": "0", "is_correct": false}, {"label": "C", "text": "1", "is_correct": false}, {"label": "D", "text": "2", "is_correct": true}], "explanation_steps": ["Step 1: Look at each term of the polynomial and note the exponent of x in each term.", "Step 2: The highest exponent of x is 2 (from the term 3x^2), so the degree of the polynomial is 2."], "solution_summary": "Final answer: C because the highest exponent of x in the polynomial is 2, which defines its degree."}, {"stem": "What is the sum of the coefficients of the quadratic polynomial 2x^2 - 5x + 3?", "concept_tag": "sum of coefficients", "correct_label": "A", "choices": [{"label": "A", "text": "0", "is_correct": true}, {"label": "B", "text": "10", "is_correct": false}, {"label": "C", "text": "-6", "is_correct": false}, {"label": "D", "text": "5", "is_correct": false}], "explanation_steps": ["Step 1: Identify the coefficients of the polynomial: 2 (for x^2), -5 (for x), and 3 (constant).", "Step 2: Add them together: 2 + (-5) + 3 = 0."], "solution_summary": "Final answer: C because 2 + (-5) + 3 equals 0, the sum of the coefficients."}, {"stem": "What is the degree of the polynomial 5x^3 - 2x + 7?", "concept_tag": "polynomial degree", "correct_label": "C", "choices": [{"label": "A", "text": "4", "is_correct": false}, {"label": "B", "text": "2", "is_correct": false}, {"label": "C", "text": "3", "is_correct": true}, {"label": "D", "text": "1", "is_correct": false}], "explanation_steps": ["Step 1: Identify the highest exponent of the variable x in the polynomial.", "Step 2: The term with the highest exponent is 5x^3, so the highest exponent is 3, which is the degree."], "solution_summary": "Final answer: C because the highest power of x in the polynomial is 3, making the degree 3."}]}','2026-07-24 01:55:29.201623','2026-07-24 01:56:01.509428',25,'%PDF-1.6 1678 0 obj <</Linearized 1/L 6327035/O 1681/E 117359/N 334/T 6324441/H [ 837 1008]>> endobj 1687 0 obj <</DecodeParms<</Columns 5/Predictor 12>>/Filter/FlateDecode/ID[<2900000023480000FF180000FF670000><49BD346E328FFC4193F197C9898BDBA7>]/Index[1678 155]/Info 1677 0 R/Length 82/Prev 6324442/Root 1679 0 R/Size 1833/Type/XRef/W[1 3 1]>>stream ``b``W endstream endobj startxref 1832 0 obj <</Filter/FlateDecode/I 1899/L 1883/Length 908/O 1867/S 1833>>stream ^}`zFw ;VD1s7 #x%/G[ Yp8&g.O endstream endobj 1679 0 obj <</Metadata 1334 0 R/OpenAction 1680 0 R/Outlines 1692 0 R/PageLabels 1671 0 R/PageLayout/SinglePage/PageMode/UseOutlines/Pages 1676 0 R/PieceI